def rle(s):
    result = []
    count = 0
    for i, char in enumerate(s):
        if i == 0 or char == s[i - 1]:
            count += 1
        else:
            result.append(f"{s[i - 1]}{count}")
            count = 1
    result.append(f"{s[-1]}{count}")
    return "".join(result)
