def merge_intervals(xs):
    if not xs:
        return []
    xs = sorted(xs)
    merged = [list(xs[0])]
    for start, end in xs[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged
