def count_islands(grid):
    """Count 4-connected groups of 1s in a grid of 0/1 lists."""
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False] * cols for _ in range(rows)]

    def flood_fill(start_r, start_c):
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if not (0 <= r < rows and 0 <= c < cols):
                continue
            if visited[r][c] or grid[r][c] != 1:
                continue
            visited[r][c] = True
            stack.append((r - 1, c))
            stack.append((r + 1, c))
            stack.append((r, c - 1))
            stack.append((r, c + 1))

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                flood_fill(r, c)
                count += 1
    return count
